// HTTP probes against a real server using raw sockets.
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import net from 'node:net';
import path from 'node:path';

const SERVER = path.resolve(import.meta.dirname, '../../server.mjs');
const dir = fs.mkdtempSync(path.join(import.meta.dirname, 'h-'));

function start(env) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [SERVER], { cwd: dir, env: { PATH: process.env.PATH, PORT: '0', ...env } });
    let out = '';
    child.stderr.on('data', (d) => process.stdout.write(`[stderr] ${d}`));
    child.stdout.on('data', (d) => {
      out += d;
      const m = /:(\d+)\n/.exec(out);
      if (m) resolve({ child, port: Number(m[1]) });
    });
    child.on('exit', (c) => reject(new Error(`exit ${c}`)));
  });
}

function raw(port, text, extra) {
  return new Promise((resolve) => {
    const s = net.connect(port, '127.0.0.1');
    let buf = Buffer.alloc(0);
    s.on('data', (d) => { buf = Buffer.concat([buf, d]); });
    s.on('error', (e) => resolve(`ERR ${e.code}`));
    s.on('close', () => resolve(buf.toString('utf8')));
    s.write(text);
    if (extra) s.write(extra);
    s.end();
  });
}

function req(port, method, target, { headers = {}, body } = {}) {
  const b = body === undefined ? undefined : Buffer.isBuffer(body) ? body : Buffer.from(body);
  const h = { Host: 'x', Connection: 'close', ...headers };
  if (b) h['Content-Length'] = b.length;
  const head = `${method} ${target} HTTP/1.1\r\n${Object.entries(h).map(([k, v]) => `${k}: ${v}`).join('\r\n')}\r\n\r\n`;
  return raw(port, head, b);
}

function summary(text) {
  const [head, ...rest] = text.split('\r\n\r\n');
  const lines = head.split('\r\n');
  const ct = lines.find((l) => /^content-type:/i.test(l)) ?? '';
  return `${lines[0]} | ${ct} | ${rest.join('\r\n\r\n').slice(0, 160)}`;
}

const J = { 'Content-Type': 'application/json' };
const bk = (o) => JSON.stringify({ room: 'Aurora', title: 'T', date: '2026-11-03', start: '09:00', end: '10:00', ...o });

const { child, port } = await start({ DATA_FILE: 'data.json' });
const probes = [
  ['GET', '/api/rooms'], ['HEAD', '/api/rooms'], ['OPTIONS', '/api/rooms'], ['POST', '/api/rooms'],
  ['GET', '/API/rooms'], ['GET', '/api/./rooms'], ['GET', '/api/%62ookings'], ['GET', '/api/bookings/'],
  ['GET', '/api/bookings/1/'], ['DELETE', '/api/bookings/'], ['GET', '/api/bookings/abc'], ['PUT', '/api/bookings'],
  ['DELETE', '/api/bookings/abc'], ['DELETE', '/api/bookings/01'], ['DELETE', '/api/bookings/0'], ['DELETE', '/api/bookings/1?x'],
  ['DELETE', '/api/bookings/%31'], ['GET', '/api/bookings?date'], ['GET', '/api/bookings?date='], ['GET', '/api/bookings?date=2026-11-03&date=x'],
  ['GET', '/api/bookings?date=x&date=2026-11-03'], ['GET', '/api/bookings?date=2026%2D11%2D03'], ['GET', '/api/bookings?Date=x'],
  ['GET', '/api/bookings?date=2100-01-01'], ['GET', '/api/bookings?date=1999-12-31'], ['GET', '/api/bookings?date=2000-02-29'],
  ['GET', '/api/bookings?date=2100-02-29'], ['GET', '/api/bookings?date=2001-02-29'], ['GET', '/api/bookings?date=2026-11-03+'],
  ['GET', '/?x=1'], ['HEAD', '/'], ['POST', '/app.js'], ['GET', '/app.js?v=2'], ['GET', '/index.html'], ['GET', '//'], ['GET', '*'],
  ['GET', 'http://x/api/rooms'],
];
for (const [m, t] of probes) console.log(m, t, '=>', summary(await req(port, m, t)));

const posts = [
  ['no CT', {}, bk()], ['CT text/plain', { 'Content-Type': 'text/plain' }, bk()],
  ['CT tab+param', { 'Content-Type': '\tAPPLICATION/Json\t ; charset=latin1' }, bk({ start: '00:00', end: '00:01' })],
  ['CT applicationjson', { 'Content-Type': 'application/jsonx' }, bk()],
  ['CT empty', { 'Content-Type': '' }, bk()],
  ['415 before 413', { 'Content-Type': 'text/plain' }, 'x'.repeat(50000)],
  ['413 exactly 10001', J, 'x'.repeat(10001)], ['400 at 10000', J, ' '.repeat(10000)],
  ['valid at 10000 bytes', J, bk({ start: '01:00', end: '02:00' }).padEnd(10000, ' ')],
  ['413 big 2MB', J, 'x'.repeat(2_000_000)],
  ['BOM', J, Buffer.concat([Buffer.from([0xef, 0xbb, 0xbf]), Buffer.from(bk())])],
  ['invalid utf8 in title', J, Buffer.concat([Buffer.from('{"room":"Cosmos","title":"a'), Buffer.from([0xff]), Buffer.from('","date":"2026-11-03","start":"09:00","end":"10:00"}')])],
  ['empty', J, ''], ['null', J, 'null'], ['array', J, '[]'], ['string', J, '"x"'], ['number', J, '1'], ['true', J, 'true'],
  ['room case', J, bk({ room: 'aurora' })], ['room missing', J, '{}'],
  ['title 80 after trim', J, bk({ title: `  ${'a'.repeat(80)}\n`, room: 'Borealis' })],
  ['title 81', J, bk({ title: 'a'.repeat(81) })], ['title spaces', J, bk({ title: '    ' })],
  ['title 80 astral (160 units)', J, bk({ title: '\u{1F600}'.repeat(41) })], ['title number', J, bk({ title: 5 })],
  ['date padded', J, bk({ date: ' 2026-11-03' })], ['date 2026-11-3', J, bk({ date: '2026-11-3' })], ['date 2099-12-31', J, bk({ date: '2099-12-31', room: 'Cosmos' })],
  ['date 2000-01-01', J, bk({ date: '2000-01-01', room: 'Cosmos' })], ['date 2024-02-30', J, bk({ date: '2024-02-30' })], ['date 2026-04-31', J, bk({ date: '2026-04-31' })],
  ['date fullwidth', J, bk({ date: '２026-11-03' })],
  ['start 9:00', J, bk({ start: '9:00' })], ['start 24:00', J, bk({ start: '24:00' })], ['end 23:60', J, bk({ end: '23:60' })],
  ['end == start', J, bk({ start: '10:00', end: '10:00' })], ['end<start', J, bk({ start: '11:00', end: '10:00' })],
  ['ok A 09-10', J, bk()], ['ok extra key', J, bk({ room: 'Aurora', start: '10:00', end: '11:00', id: 99, extra: 1 })],
  ['409 overlap both', J, bk({ start: '08:00', end: '12:00' })], ['ok touching', J, bk({ start: '11:00', end: '12:00' })],
  ['409 inside', J, bk({ start: '09:30', end: '09:45' })],
  ['order: room before title', J, '{"room":"x","title":""}'],
];
for (const [label, h, b] of posts) console.log('POST', label, '=>', summary(await req(port, 'POST', '/api/bookings', { headers: h, body: b })));

console.log('LIST =>', summary(await req(port, 'GET', '/api/bookings')));
console.log('DELETE 1 =>', summary(await req(port, 'DELETE', '/api/bookings/1')));
console.log('DELETE 1 again =>', summary(await req(port, 'DELETE', '/api/bookings/1')));
console.log('DELETE with body =>', summary(await req(port, 'DELETE', '/api/bookings/999', { body: 'x'.repeat(100000) })));

// Concurrency: 20 overlapping posts at once.
const results = await Promise.all(Array.from({ length: 20 }, (_, i) => req(port, 'POST', '/api/bookings', { headers: J, body: bk({ room: 'Cosmos', date: '2030-01-01', start: '09:00', end: `1${i % 10}:00` }) })));
console.log('concurrent statuses:', results.map((r) => r.split(' ')[1]).join(','));
const many = await Promise.all(Array.from({ length: 20 }, (_, i) => req(port, 'POST', '/api/bookings', { headers: J, body: bk({ room: 'Borealis', date: '2031-01-01', start: `${String(i).padStart(2, '0')}:00`, end: `${String(i).padStart(2, '0')}:30` }) })));
const ids = many.map((r) => JSON.parse(r.split('\r\n\r\n')[1]).id);
console.log('distinct ids:', new Set(ids).size, 'of', ids.length);

// Chunked large body for 413 with chunked encoding.
const chunk = 'x'.repeat(5000);
let chunked = `POST /api/bookings HTTP/1.1\r\nHost: x\r\nConnection: close\r\nContent-Type: application/json\r\nTransfer-Encoding: chunked\r\n\r\n`;
for (let i = 0; i < 200; i += 1) chunked += `${(5000).toString(16)}\r\n${chunk}\r\n`;
chunked += '0\r\n\r\n';
console.log('chunked 1MB =>', summary(await raw(port, chunked)));

console.log('data file:', fs.readFileSync(path.join(dir, 'data.json'), 'utf8').slice(0, 200));
child.kill();

// Restart persistence, then save failure.
const s2 = await start({ DATA_FILE: 'data.json' });
console.log('after restart POST =>', summary(await req(s2.port, 'POST', '/api/bookings', { headers: J, body: bk({ date: '2040-01-01' }) })));
s2.child.kill();

const s3 = await start({ DATA_FILE: 'gone/data.json' });
console.log('save fail POST =>', summary(await req(s3.port, 'POST', '/api/bookings', { headers: J, body: bk() })));
console.log('save fail list =>', summary(await req(s3.port, 'GET', '/api/bookings')));
console.log('still alive =>', summary(await req(s3.port, 'GET', '/api/rooms')));
fs.mkdirSync(path.join(dir, 'gone'));
console.log('after mkdir POST id =>', summary(await req(s3.port, 'POST', '/api/bookings', { headers: J, body: bk() })));
console.log('gone listing:', fs.readdirSync(path.join(dir, 'gone')));
// Make the data file a directory so DELETE save fails.
fs.rmSync(path.join(dir, 'gone', 'data.json'));
fs.mkdirSync(path.join(dir, 'gone', 'data.json'));
console.log('delete save fail =>', summary(await req(s3.port, 'DELETE', '/api/bookings/1')));
console.log('list after =>', summary(await req(s3.port, 'GET', '/api/bookings')));
console.log('gone listing:', fs.readdirSync(path.join(dir, 'gone')));
s3.child.kill();
fs.rmSync(dir, { recursive: true, force: true });

