41	  });
42	  const out = { stdout: '', stderr: '' };
43	  child.stdout.setEncoding('utf8').on('data', (d) => { out.stdout += d; });
44	  child.stderr.setEncoding('utf8').on('data', (d) => { out.stderr += d; });
45	  const exited = new Promise((resolve) => {
